package com.hrms.shift.controller;
import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.responses.*;import com.hrms.shift.dto.*;import com.hrms.shift.model.ShiftStatus;import com.hrms.shift.repository.*;import com.hrms.shift.service.ShiftService;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/shifts") @Tag(name="Shifts") @SecurityRequirement(name="bearerAuth") @PreAuthorize("hasRole('ADMIN')")
public class ShiftController {private final ShiftService service;private final ClockSource clock;public ShiftController(ShiftService s,ClockSource c){service=s;clock=c;}
 @PostMapping public ApiResponse<ShiftResponse> create(@Valid @RequestBody CreateShiftRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Shift created",service.create(r,a),clock);}
 @GetMapping public ApiResponse<ShiftPageResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String search,@RequestParam(required=false)ShiftStatus status,@RequestParam(defaultValue="createdAt")String sortBy,@RequestParam(defaultValue="desc")String sortDirection){return ApiResponse.success("Shifts retrieved",service.list(new ShiftSearch(search,status,page,limit,sortBy,sortDirection)),clock);}
 @GetMapping("/{id}") public ApiResponse<ShiftResponse> get(@PathVariable String id){return ApiResponse.success("Shift retrieved",service.get(id),clock);}
 @PatchMapping("/{id}") public ApiResponse<ShiftResponse> update(@PathVariable String id,@Valid @RequestBody UpdateShiftRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Shift updated",service.update(id,r,a),clock);}
 @PatchMapping("/{id}/deactivate") public ApiResponse<ShiftResponse> deactivate(@PathVariable String id,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Shift deactivated",service.deactivate(id,a),clock);}
 @PatchMapping("/{id}/reactivate") public ApiResponse<ShiftResponse> reactivate(@PathVariable String id,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Shift reactivated",service.reactivate(id,a),clock);}}
